package com.alpharip.staffmod.AuditFindingsBoard; public final class AuditFindingAssignment { private final String assignee,assignedBy; private final long assignedAt; public AuditFindingAssignment(String a,String by,long at){if(a==null||a.trim().isEmpty())throw new IllegalArgumentException("Assignee is required");assignee=a.trim();assignedBy=by==null?"":by.trim();assignedAt=Math.max(0L,at);} public String getAssignee(){return assignee;} public String getAssignedBy(){return assignedBy;} public long getAssignedAt(){return assignedAt;} }
